import json
s=json.load(open('/app/output/spec.json'))
for k in ['static','robot_spec','cameras','action_types','proprio_groups','default_cameras','max_call_wall_s','on_service_error','control_hz']:
 print('\n###',k)
 v=s.get(k)
 if k=='static':
  print('sheet-related', {x:y for x,y in v.items() if x in ('sheets','paper_frame','wells')})
  print('all static keys',v.keys())
  for x,y in v.items():
   if x not in ('wells','sheets','target_image'): print(x,y)
 elif k=='cameras':
  print(json.dumps(v,indent=2)[:8000])
 else: print(json.dumps(v,indent=2)[:8000])
